                        || EVP_EncryptFinal_ex(ed_ctx, discard, &outdl) != 1
                        || outdl != 0) {
                sc_log(card->ctx,"SM encode failed in OpenSSL");
                piv_log_openssl(card->ctx);
                r = SC_ERROR_SM_AUTHENTICATION_FAILED;
                goto err;
